#region

using System.Buffers.Binary;
using System.Text;

#endregion

namespace Cs2VideoGenerator.Core.Tests.TestSupport;

/// <summary>
///     Writes RIFF wav files by hand, including the unfinished shapes an engine leaves behind while it
///     is still recording. Hand-built rather than generated by ffmpeg because the states worth testing
///     - a placeholder data size, a chunk between <c>fmt </c> and <c>data</c>, an odd chunk length -
///     are exactly the ones a correct writer never produces.
/// </summary>
public static class WavFixture
{
    private const int SampleRate = 48000;
    private const int Channels = 2;
    private const int BitsPerSample = 16;

    /// <summary>Bytes of audio per second at the fixture's format.</summary>
    public static int BytesPerSecond => SampleRate * Channels * (BitsPerSample / 8);

    /// <summary>
    ///     Writes a wav of the given length.
    /// </summary>
    /// <param name="path">Where to write it.</param>
    /// <param name="seconds">Length of the audio.</param>
    /// <param name="finalized">
    ///     False writes the file an engine leaves mid-recording: the samples are there, but the
    ///     <c>data</c> chunk still declares the placeholder size it was opened with.
    /// </param>
    /// <param name="extraChunkBeforeData">
    ///     Writes a <c>LIST</c> chunk of this many bytes between <c>fmt </c> and <c>data</c>. An odd
    ///     length exercises the pad-to-even rule.
    /// </param>
    public static void Write(string path, double seconds, bool finalized = true, int extraChunkBeforeData = 0)
    {
        int dataBytes = (int)Math.Round(seconds * BytesPerSecond);
        dataBytes -= dataBytes % (Channels * (BitsPerSample / 8));

        using FileStream stream = new(path, FileMode.Create, FileAccess.Write, FileShare.None);
        using BinaryWriter writer = new(stream, Encoding.ASCII, true);

        int extraChunkTotal = extraChunkBeforeData > 0
            ? 8 + extraChunkBeforeData + (extraChunkBeforeData % 2)
            : 0;

        writer.Write("RIFF"u8);
        writer.Write(36 + extraChunkTotal + dataBytes);
        writer.Write("WAVE"u8);

        writer.Write("fmt "u8);
        writer.Write(16);
        writer.Write((short)1);
        writer.Write((short)Channels);
        writer.Write(SampleRate);
        writer.Write(BytesPerSecond);
        writer.Write((short)(Channels * (BitsPerSample / 8)));
        writer.Write((short)BitsPerSample);

        if (extraChunkBeforeData > 0)
        {
            writer.Write("LIST"u8);
            writer.Write(extraChunkBeforeData);
            writer.Write(new byte[extraChunkBeforeData + (extraChunkBeforeData % 2)]);
        }

        writer.Write("data"u8);

        // The engine cannot know the sample count while it is streaming, so it writes a placeholder
        // and corrects it when it closes the file. That is a different state from "no audio".
        writer.Write(finalized ? dataBytes : 0);
        writer.Write(new byte[dataBytes]);
    }

    /// <summary>
    ///     Writes a wav whose <c>data</c> chunk declares far more audio than the file contains - the
    ///     other placeholder shape, where the writer reserved a maximum rather than a zero.
    /// </summary>
    public static void WriteOverDeclared(string path, double seconds)
    {
        Write(path, seconds);

        byte[] contents = File.ReadAllBytes(path);
        int dataSizeOffset = FindDataSizeOffset(contents);
        BinaryPrimitives.WriteUInt32LittleEndian(contents.AsSpan(dataSizeOffset), 0x7FFFFFFF);
        File.WriteAllBytes(path, contents);
    }

    private static int FindDataSizeOffset(byte[] contents)
    {
        for (int i = 12; i + 8 <= contents.Length; i++)
        {
            if (contents[i] == (byte)'d' && contents[i + 1] == (byte)'a' &&
                contents[i + 2] == (byte)'t' && contents[i + 3] == (byte)'a')
            {
                return i + 4;
            }
        }

        throw new InvalidOperationException("The fixture wav has no data chunk");
    }
}
